'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat32Array = require( '@stdlib/assert/is-same-float32array' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var Float32Array = require( '@stdlib/array/float32' );
var cfloorf = require( './../lib/assign.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cfloorf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function rounds each component of a single-precision complex floating-point number toward negative infinity', function test( t ) {
	var expected;
	var out;
	var v;

	out = new Float32Array( 2 );
	v = cfloorf( -1.5, 2.5, out, 1, 0 );

	expected = new Float32Array( [ -2.0, 2.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cfloorf( -1.5, 2.5, out, 2, 0 );

	expected = new Float32Array( [ -2.0, 0.0, 2.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cfloorf( -1.5, 2.5, out, 2, 1 );

	expected = new Float32Array( [ 0.0, -2.0, 0.0, 2.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cfloorf( -1.5, 2.5, out, -2, 3 );

	expected = new Float32Array( [ 0.0, 2.0, 0.0, -2.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function rounds real and imaginary components to the largest integer smaller than or equal to a given number', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cfloorf( -4.2, 5.5, out, 1, 0 );

	expected = new Float32Array( [ -5.0, 5.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cfloorf( 9.99999, 0.1, out, 1, 0 );

	expected = new Float32Array( [ 9.0, 0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 2 );
	cfloorf( 0.0, 0.0, out, 1, 0 );

	expected = new Float32Array( [ 0.0, 0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns a `NaN` if provided a `NaN`', function test( t ) {
	var out = new Float32Array( 2 );

	cfloorf( NaN, NaN, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cfloorf( -0.0, -0.0, out, 1, 0 );

	expected = new Float32Array( [ -0.0, -0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cfloorf( +0.0, +0.0, out, 1, 0 );

	expected = new Float32Array( [ +0.0, +0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cfloorf( PINF, PINF, out, 1, 0 );

	expected = new Float32Array( [ PINF, PINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cfloorf( NINF, NINF, out, 1, 0 );

	expected = new Float32Array( [ NINF, NINF ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});
